import type { Trace } from "@java-visuals/trace-schema";
import { checkTrace } from "@java-visuals/trace-schema";
import type { LessonScript } from "../player/script";
import { unresolvedAnchors } from "../player/script";
import type { LessonEntry } from "./curriculum";
import { parseNarration } from "./narration";

// Bundled at build time. Traces are generated by `npm run record` and not committed.
const traceFiles = import.meta.glob<Trace>("../../../lessons/*/*/traces/*.json", { eager: true, import: "default" });
const narrationFiles = import.meta.glob<string>("../../../lessons/*/*/narration.md", {
  eager: true,
  query: "?raw",
  import: "default",
});

/** A Lesson's narration.md as a LessonScript. */
export function loadScript(lesson: LessonEntry): LessonScript {
  const source = narrationFiles[`../../../lessons/${lesson.id}/narration.md`];
  if (source === undefined) throw new Error(`${lesson.id}: missing narration.md`);
  return { title: lesson.data.title, ...parseNarration(source, `lessons/${lesson.id}/narration.md`) };
}

export interface ExecutionLessonData {
  variants: Record<string, Trace>;
  variantLabels: Record<string, string>;
  script: LessonScript;
}

/** Everything the Player needs for one Execution Lesson; fails the build on missing or inconsistent content. */
export function loadExecutionLesson(lesson: LessonEntry): ExecutionLessonData {
  const variants: Record<string, Trace> = {};
  const variantLabels: Record<string, string> = {};
  for (const { id, label } of lesson.data.variants) {
    const trace = traceFiles[`../../../lessons/${lesson.id}/traces/${id}.json`];
    if (!trace) {
      throw new Error(`${lesson.id}: no Trace for Variant "${id}". Run \`npm run record\` first.`);
    }
    const problems = checkTrace(trace);
    if (problems.length) throw new Error(`${lesson.id} [${id}]: invalid Trace:\n  ${problems.join("\n  ")}`);
    variants[id] = trace;
    variantLabels[id] = label;
  }

  const script = loadScript(lesson);

  for (const entry of [...script.narration, ...script.prompts]) {
    if (entry.variant && !(entry.variant in variants)) {
      throw new Error(`${lesson.id}: narration.md mentions Variant "${entry.variant}", which lesson.yaml doesn't list`);
    }
  }
  for (const [id, trace] of Object.entries(variants)) {
    const missing = unresolvedAnchors(script, trace, id);
    if (missing.length) {
      throw new Error(`${lesson.id} [${id}]: narration.md refers to Markers the Lesson Program doesn't have: ${missing.join(", ")}`);
    }
  }
  return { variants, variantLabels, script };
}
